<?php
require __DIR__ . '/auth.php'; require_login(); require __DIR__ . '/conexion.php';
$msg=''; $err='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 $doc=trim($_POST['documento']??''); $nombre=trim($_POST['nombre']??''); $tel=trim($_POST['telefono']??''); $correo=trim($_POST['correo']??'');
 if($doc===''||$nombre==='') $err='El documento y el nombre son obligatorios.';
 else { $s=$mysqli->prepare('INSERT INTO clientes(documento,nombre,telefono,correo) VALUES(?,?,?,?)'); $s->bind_param('ssss',$doc,$nombre,$tel,$correo); if($s->execute())$msg='Cliente guardado.';else $err='No se pudo guardar; verifica que el documento no esté duplicado.'; $s->close(); }
}
$rows=$mysqli->query('SELECT documento,nombre,telefono,correo FROM clientes ORDER BY nombre');
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Clientes</title><style>body{font:15px Arial;background:#f2f7f5;margin:0;color:#243b37}.wrap{padding:22px}.box{background:white;padding:20px;border-radius:12px;margin-bottom:16px}h1,h2{color:#087f73}form{display:flex;gap:10px;flex-wrap:wrap}input,button{padding:10px;border:1px solid #ccd;border-radius:7px}input{flex:1;min-width:150px}button,.btn{background:#087f73;color:white;border:0;padding:10px 14px;border-radius:7px;text-decoration:none}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:9px;border-bottom:1px solid #ddd}.msg{padding:10px;background:#e2f4ed}</style></head><body><main class="wrap"><section class="box"><h1>Clientes</h1><p><?php echo htmlspecialchars($msg?:$err); ?></p><form method="post"><input name="documento" placeholder="Cédula o código" required><input name="nombre" placeholder="Nombre del cliente" required><input name="telefono" placeholder="Teléfono"><input type="email" name="correo" placeholder="Correo"><button>Guardar cliente</button><a class="btn" href="index.php">Volver</a></form></section><section class="box"><h2>Clientes registrados</h2><table><thead><tr><th>Documento</th><th>Nombre</th><th>Teléfono</th><th>Correo</th></tr></thead><tbody><?php while($c=$rows->fetch_assoc()){ ?><tr><td><?=htmlspecialchars($c['documento'])?></td><td><?=htmlspecialchars($c['nombre'])?></td><td><?=htmlspecialchars($c['telefono']??'')?></td><td><?=htmlspecialchars($c['correo']??'')?></td></tr><?php } ?></tbody></table></section></main></body></html>
